const source = $input.first().json;
const maxChars = Number(source.max_chars_per_part || 3500);
const rawText = String(source.book_text || '').trim();

if (!rawText) {
  throw new Error('book_text is empty. Add text in the Set node first.');
}

const paragraphs = rawText.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
const chunks = [];
let current = '';

for (const paragraph of paragraphs) {
  const candidate = current ? `${current}\n\n${paragraph}` : paragraph;
  if (candidate.length <= maxChars) {
    current = candidate;
  } else {
    if (current) chunks.push(current);
    if (paragraph.length <= maxChars) {
      current = paragraph;
    } else {
      for (let i = 0; i < paragraph.length; i += maxChars) {
        chunks.push(paragraph.slice(i, i + maxChars));
      }
      current = '';
    }
  }
}
if (current) chunks.push(current);

return chunks.map((text, index) => ({
  json: {
    book_title: source.book_title || 'audiobook',
    model: source.model || 'gpt-4o-mini-tts',
    voice: source.voice || 'alloy',
    part_number: index + 1,
    output_filename: `${(source.book_title || 'audiobook').toLowerCase().replace(/[^a-z0-9]+/g, '-')}-part-${String(index + 1).padStart(2, '0')}.mp3`,
    input_text: text
  }
}));

for (const item of $input.all()) {
  if (!item.binary?.audio) {
    throw new Error('No audio binary was returned from OpenAI.');
  }
  item.binary.audio.fileName = item.json.output_filename;
  item.binary.audio.mimeType = 'audio/mpeg';
}
return $input.all();
